files.content:
* { box-sizing: border-box; }

:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #172a3a;
  background: #eaf1ed;
}

body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 15% 15%, #f8e9c8 0, transparent 28%), #eaf1ed;
}

.card {
  width: min(100%, 520px);
  padding: clamp(22px, 6vw, 40px);
  border: 1px solid #d7e2dc;
  border-radius: 24px;
  background: #fffefa;
  box-shadow: 0 20px 60px #172a3a18;
}

header { text-align: center; }
.eyebrow { margin: 0 0 8px; color: #b56b3c; font-size: .82rem; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(1.8rem, 7vw, 2.4rem); letter-spacing: -.04em; }
.intro { max-width: 360px; margin: 12px auto 26px; color: #5c6d72; line-height: 1.55; }

.board-wrap { display: grid; place-items: center; }
.board {
  position: relative;
  width: min(100%, 340px);
  aspect-ratio: 1;
  overflow: hidden;
  border: 4px solid #172a3a;
  border-radius: 12px;
  background-color: #dce9df;
  background-image: linear-gradient(#a9c1b4 1px, transparent 1px), linear-gradient(90deg, #a9c1b4 1px, transparent 1px);
  background-size: 20% 20%;
  box-shadow: 0 8px 0 #172a3a;
}
.robot {
  position: absolute;
  width: 20%;
  height: 20%;
  display: grid;
  place-items: center;
  color: #fffefa;
  transition: left 160ms ease, top 160ms ease, transform 160ms ease;
}
.robot::before {
  content: "";
  position: absolute;
  inset: 13%;
  border: 3px solid #172a3a;
  border-radius: 7px;
  background: #df8051;
  box-shadow: inset -5px -5px 0 #b75e3b;
}
.robot-face { position: relative; z-index: 1; font-size: 1.7rem; line-height: 1; text-shadow: 1px 1px #172a3a; }

.status { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 28px 0 20px; }
.status > div { padding: 12px 14px; border-radius: 12px; background: #f0f4ef; }
.status-label { display: block; margin-bottom: 3px; color: #64756f; font-size: .8rem; }
.status strong { font-size: .98rem; }
.controls { display: grid; gap: 10px; }
.turn-controls { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.button, .reset-button {
  min-height: 48px;
  padding: 10px 14px;
  border: 2px solid #172a3a;
  border-radius: 12px;
  color: #172a3a;
  background: #fffefa;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  transition: transform 100ms ease, background 120ms ease, box-shadow 120ms ease;
}
.button-primary { color: #fffefa; background: #246b63; border-color: #246b63; }
.button:hover, .reset-button:hover { background: #e4eee8; }
.button-primary:hover { background: #1b5b54; }
.button:focus-visible, .reset-button:focus-visible { outline: 4px solid #e5aa62; outline-offset: 3px; }
.button:active, .reset-button:active { transform: translateY(2px); box-shadow: inset 0 2px 4px #172a3a30; }
.reset-button { border-color: transparent; color: #5c6d72; background: transparent; }
.hint { margin: 16px 0 0; color: #718079; text-align: center; font-size: .85rem; }

@media (max-width: 400px) {
  body { padding: 18px 12px; }
  .card { border-radius: 18px; }
  .status { gap: 8px; }
  .status > div { padding: 10px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; }
}

const robot = document.querySelector('#robot');
const positionLabel = document.querySelector('#position');
const directionLabel = document.querySelector('#direction');

const headings = [
  { name: 'Right', symbol: '→', dx: 1, dy: 0 },
  { name: 'Down', symbol: '↓', dx: 0, dy: 1 },
  { name: 'Left', symbol: '←', dx: -1, dy: 0 },
  { name: 'Up', symbol: '↑', dx: 0, dy: -1 }
];
let row = 0;
let column = 0;
let heading = 0;

function render() {
  robot.style.left = `${column * 20}%`;
  robot.style.top = `${row * 20}%`;
  robot.setAttribute('aria-label', `Robot at row ${row + 1}, column ${column + 1}, facing ${headings[heading].name.toLowerCase()}`);
  positionLabel.textContent = `Row ${row + 1}, Column ${column + 1}`;
  directionLabel.textContent = `${headings[heading].name} ${headings[heading].symbol}`;
}

document.querySelector('#forward').addEventListener('click', () => {
  const nextColumn = column + headings[heading].dx;
  const nextRow = row + headings[heading].dy;
  if (nextColumn >= 0 && nextColumn < 5 && nextRow >= 0 && nextRow < 5) {
    column = nextColumn;
    row = nextRow;
  }
  render();
});

document.querySelector('#left').addEventListener('click', () => {
  heading = (heading + 3) % 4;
  render();
});

document.querySelector('#right').addEventListener('click', () => {
  heading = (heading + 1) % 4;
  render();
});

document.querySelector('#reset').addEventListener('click', () => {
  row = 0;
  column = 0;
  heading = 0;
  render();
});

render();
